sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
   if (isLoading || newValue==='') {
      return;
   }
   var email = new GlideAjax('GetEmailAddress');
   email.addParam('sysparm_name', 'getEmailAddress');
   email.addParam('sysparm_userID', g_form.getValue('u_requested_for'));
   email.getXMLAnswer(populateEmailAddress);


   function populateEmailAddress(answer){
	g_form.clearValue('email');
	g_form.setValue('email', answer);
   }

   //Type appropriate comment here, and begin script below

}
